      priv: {
        seoTitle: 'Privacy Policy',
        seoDesc: 'Meu Ovo platform privacy policy. Learn how we care for and protect your personal data.',
        backHome: 'Back to home',
        heroA: 'Privacy',
        heroB: 'Policy',
        updated: 'Last updated: August 2026',
        s1Title: '1. Data We Collect',
        s1Body: 'We collect information you provide directly: name, email, phone/WhatsApp, address and profile photo. When you place an order, we record the chosen items, amount, payment method and delivery address. Registered restaurants provide additional data such as tax ID, business address, banking data and menu information.',
        s2Title: '2. How We Use Your Data',
        s2Body: 'Your data is used to: (a) process and deliver your orders; (b) communicate order status via WhatsApp; (c) improve the platform experience; (d) send relevant communications (with your consent); (e) generate anonymous usage reports; (f) prevent fraud and abuse. Your data is never sold to third parties.',
        s3Title: '3. Data Sharing',
        s3Body: 'We share your data only with the partner Restaurant when you place an order (name, phone and delivery address), and with essential service providers (hosting, analytics, email delivery). We require all partners to treat your data with the same level of security and respect.',
        s4Title: '4. Data Security',
        s4Body: 'We adopt robust technical and organizational measures to protect your data against unauthorized access, alteration, disclosure or destruction. This includes encryption in transit (SSL/TLS), firewalls, restricted access controls and continuous security monitoring. Our servers are hosted by certified providers.',
        s5Title: '5. Cloud Data and Artificial Intelligence',
        s5Body: 'Our platform is hosted on Google Cloud (Firebase), with encryption in transit (TLS 1.2+) and at rest (AES-256). Generative artificial intelligence features (Google Gemini) are used only when you choose to use them: to generate menu suggestions and product descriptions ("Generate with AI" button in the dashboard) and to answer questions in WhatsApp support. In these cases, we send the AI only the information needed for the task (such as a product name and category) — we never send customer personal data. AI-generated results are mere suggestions and pass your review before any publication. You can use the platform normally without enabling any AI feature.',
        s6Title: '6. Cookies and Technologies',
        s6Body: 'We use strictly necessary cookies for the platform to work (authentication and preferences). Analytics tools (Google Analytics) and ads (Meta Pixel) are only enabled after your explicit consent. You can accept, decline or change your choice at any time using the "Cookies" button in the site footer. When you decline analytics cookies, no tracking tool is loaded on your device.',
        s7Title: '7. Your Rights',
        s7Body: 'Under data protection law, you have the right to: (a) confirm the existence of data processing; (b) access your data; (c) correct incomplete or outdated data; (d) request anonymization or deletion; (e) revoke consent; (f) request portability. In your profile you will find the "Download my data" and "Delete my account" options. To exercise any other right, contact us.',
        s8Title: '8. Retention and Deletion',
        s8Body: 'We keep your data for as long as needed to fulfill the described purposes or to meet legal obligations. When you delete your account via the "Delete my account" option in your profile, your personal data is immediately removed from our database (orders and personal data), except where the law requires longer retention (such as tax transaction records).',
        s9Title: '9. Data Officer (DPO)',
        s9Body: 'The platform’s Data Protection Officer (DPO) is Meu OVO itself, reachable at contato@meuovo.com. The Officer is responsible for receiving complaints and communications from data subjects and taking action on personal data processing.',
        contactLine: 'Questions about your data? Talk to us:',
      },
      terms: {
        seoTitle: 'Terms of Use',
        seoDesc: 'Meu Ovo platform terms and conditions. Know your rights and duties when using our services.',
        backHome: 'Back to home',
        heroA: 'Terms of',
        heroB: 'Use',
        updated: 'Last updated: August 2026',
        t1Title: '1. Acceptance of Terms',
        t1Body: 'By accessing or using the Meu Ovo platform, you confirm that you have read, understood and agree to be bound by these Terms of Use. If you do not agree with any part of these terms, do not use our services. These terms may be updated periodically; continued use after changes constitutes acceptance of the new conditions.',
        t2Title: '2. Definitions',
        t2Body: '"Platform" refers to the Meu Ovo website, app and services. "Restaurant" or "Partner" is the registered establishment offering products through the platform. "Customer" or "User" is the individual using the platform to place orders. "Order" is the product purchase request placed by the Customer with the Restaurant.',
        t3Title: '3. Registration and Account',
        t3Body: 'To use certain features, you will need to create an account. You are responsible for keeping your credentials confidential and for all activities under your account. Information provided must be accurate, complete and up to date. The platform reserves the right to refuse or cancel registrations at its discretion.',
        t4Title: '4. Restaurant Responsibilities',
        t4Body: 'The Restaurant is solely responsible for the quality, preparation, delivery and safety of products advertised and sold through the platform. The Restaurant must keep its menu updated, price products correctly, meet estimated delivery times and comply with current health regulations. The platform is not liable for any issues in order fulfillment.',
        t5Title: '5. Payments and Transactions',
        t5Body: 'The Meu Ovo platform does not process or intermediate payments between Customers and Restaurants. All financial transactions are the sole responsibility of the Restaurant, which sets its own payment methods (PIX, credit, debit, voucher, cash). Customers must resolve any billing, refund or chargeback issues directly with the Restaurant.',
        t6Title: '6. Artificial Intelligence and Generated Content',
        t6Body: 'The platform offers AI-assisted features (Google Gemini), such as generating menu suggestions, product descriptions and WhatsApp support answers. AI-generated content is only a suggestion: the Restaurant is solely responsible for reviewing, correcting and approving any AI-generated text, price, image or information before publication, and for ensuring content accuracy and compliance. The platform may modify, suspend or discontinue AI features at any time without notice.',
        t7Title: '7. Limitation of Liability',
        t7Body: 'The Meu Ovo platform acts exclusively as a technology tool connecting Restaurants and Customers. We are not liable for: (a) delivery delays; (b) product quality or quantity; (c) improper charges; (d) damages from platform misuse; (e) temporary service unavailability. Platform liability is limited to the maximum legally permitted amount.',
        t8Title: '8. Intellectual Property',
        t8Body: 'All platform content, including logos, texts, images, source code and design, belongs to Meu Ovo or its licensors. Reproduction, distribution, modification or unauthorized use of any content is prohibited without prior written authorization.',
        t9Title: '9. General Provisions',
        t9Body: 'These Terms are governed by Brazilian law. Any dispute shall be resolved in the courts of São Paulo - SP. If any provision is deemed invalid or unenforceable, the remaining provisions stay in full force. Failure to exercise any right does not constitute a waiver.',
        contactLine: 'Questions? Contact us by email',
      },
